from decimal import Decimal; import pytest; from src.extraction.extension.brokerage_positions import UnsupportedBrokerageCsvError, classify_brokerage_csv, parse_brokerage_csv_payload, parse_brokerage_positions, parse_brokerage_positions_csv_rows; from src.extraction.extension.service import ExtractionError, ExtractionService; BROKERAGE_POSITIONS_CSV = b'Symbol,Quantity,Current Price,Market Value,Currency,P&L\nAAA,10,100.00,1000.00,USD,50.00\nBBB,5,20.00,100.00,USD,-10.00\n'; BROKERAGE_TRADE_HISTORY_CSV = b'Side,Symbol,Fill Quantity,Fill Price,Fill Amount,Fill Time,Fees,Total\nBUY,AAA,10,100.00,1000.00,2026-01-02 09:30:00,1.00,1001.00\nSELL,BBB,5,20.00,100.00,2026-01-03 10:00:00,1.00,99.00\n'; BANK_TRANSACTION_CSV = b'Transaction Date,Reference,Debit Amount,Credit Amount,Transaction Ref1\n15 Jan 2025,REF001,,500.00,SALARY\n16 Jan 2025,REF002,100.00,,GROCERIES\n'
def test_classify_brokerage_csv_distinguishes_schemas():
    'AC-extraction.332.1 AC-extraction.332.2 AC-extraction.332.3'; assert classify_brokerage_csv(['Symbol', 'Quantity', 'Market Value', 'Currency']) == 'positions'; assert classify_brokerage_csv(['Side', 'Symbol', 'Fill Quantity', 'Fill Price', 'Total']) == 'trade_history'; assert classify_brokerage_csv(['Transaction Date', 'Debit Amount', 'Credit Amount']) is None; assert classify_brokerage_csv([]) is None; 'AC-extraction.332.1'; 'AC-extraction.332.1'; _m1_headers = ['Symbol', 'Quantity', 'Market Value', 'Currency']; _m1_rows = [{'Symbol': 'AAA', 'Quantity': '10', 'Market Value': '1,000.00', 'Currency': 'usd'}, {'Symbol': '', 'Quantity': '1', 'Market Value': '5.00', 'Currency': 'USD'}]; _m1_positions = parse_brokerage_positions_csv_rows(_m1_headers, _m1_rows, broker='Interactive Brokers'); assert len(_m1_positions) == 1; _m1_pos = _m1_positions[0]; assert _m1_pos['asset_identifier'] == 'AAA'; assert Decimal(_m1_pos['quantity']) == Decimal('10'); assert Decimal(_m1_pos['market_value']) == Decimal('1000.00'); assert _m1_pos['currency'] == 'USD'; 'AC-extraction.332.2'; 'AC-extraction.332.2'; _m2_headers = ['Side', 'Symbol', 'Fill Quantity', 'Fill Price', 'Total']
    with pytest.raises(UnsupportedBrokerageCsvError, match='trade-history'): parse_brokerage_csv_payload(_m2_headers, [], institution='Interactive Brokers')
async def test_AC17_32_1_brokerage_positions_csv_produces_positions_payload(): 'AC-extraction.332.1'; service = ExtractionService(); payload = await service._parse_csv_content(BROKERAGE_POSITIONS_CSV, 'Interactive Brokers'); assert 'positions' in payload; assert len(payload['positions']) == 2; assert payload['balance_source'] == 'brokerage_positions_csv'; snapshots = parse_brokerage_positions(payload, institution='Interactive Brokers'); assert len(snapshots) == 2; assert snapshots[0].asset_identifier == 'AAA'; assert snapshots[0].quantity == Decimal('10'); assert snapshots[0].market_value == Decimal('1000.00'); assert snapshots[0].currency == 'USD'
async def test_AC17_32_2_brokerage_trade_history_csv_raises_actionable_error():
    'AC-extraction.332.2'; service = ExtractionService()
    with pytest.raises(ExtractionError) as excinfo: await service._parse_csv_content(BROKERAGE_TRADE_HISTORY_CSV, 'Interactive Brokers')
    message = str(excinfo.value); assert 'trade-history' in message.lower(); assert 'No valid transactions found' not in message
async def test_AC17_32_3_bank_csv_unaffected_by_brokerage_detection(): 'AC-extraction.332.3'; service = ExtractionService(); payload = await service._parse_csv_content(BANK_TRANSACTION_CSV, 'DBS'); assert 'positions' not in payload; assert len(payload['transactions']) == 2; assert payload['transactions'][0]['direction'] == 'IN'; assert payload['transactions'][0]['amount'] == '500.00'; assert payload['transactions'][1]['direction'] == 'OUT'; assert payload['transactions'][1]['amount'] == '100.00'
